# Controller to pull forward away from the left rail, then reverse following the lane curvature via camera points.

phase = 'unpin'
fwd_start_progress = None

def control(obs):
    global phase, fwd_start_progress

    look_deg = -23.0

    motion = obs.get('motion', {})
    hold_s = motion.get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    covered = obs['progress']['covered']
    cam = obs.get('views', {}).get('camera')

    if hold_s > 0.05:
        return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    if phase == 'unpin':
        fwd_start_progress = covered
        phase = 'pull_forward'

    if phase == 'pull_forward':
        if fwd_start_progress is not None and (fwd_start_progress - covered) < 1.8:
            return {'steer_deg': -5.0, 'speed_mps': 0.8, 'look_deg': look_deg}
        else:
            phase = 'reverse'

    # Reverse phase
    speed_mps = -0.7
    target_hitch = 0.0

    if cam and 'walls' in cam and len(cam['walls']) > 0:
        left_dists = [d for b, d in cam['walls'] if b > 0 and d < 4.0]
        right_dists = [d for b, d in cam['walls'] if b < 0 and d < 4.0]

        min_left = min(left_dists, default=9.0)
        min_right = min(right_dists, default=9.0)

        base_hitch = 0.0
        if covered > 9.0 and covered < 18.0:
            base_hitch = -10.0
        elif covered >= 18.0:
            base_hitch = 0.0

        if min_left < 1.3:
            target_hitch = -13.0
        elif min_right < 1.3:
            target_hitch = +10.0
        else:
            diff = min_left - min_right
            target_hitch = base_hitch + max(-7.0, min(7.0, diff * 5.0))
    else:
        if covered > 9.0 and covered < 18.0:
            target_hitch = -10.0
        else:
            target_hitch = 0.0

    hitch_err = hitch - target_hitch
    steer_deg = 2.4 * hitch_err
    steer_deg = max(-32.0, min(32.0, steer_deg))

    return {'steer_deg': steer_deg, 'speed_mps': speed_mps, 'look_deg': look_deg}

