import math

state = {
    'pull_forward': True,
    'forward_ticks': 0,
}

def control(obs):
    global state
    look_deg = -41.0

    hitch = obs.get('hitch_deg', 0.0)
    views = obs.get('views', {})
    cam = views.get('camera', {})

    status = obs.get('status', '')
    if status == 'PINNED' or state['pull_forward']:
        state['forward_ticks'] += 1
        # Pull forward gently with steer to move away from rail
        if state['forward_ticks'] < 35:
            return {'steer_deg': -10.0, 'speed_mps': 1.5, 'look_deg': look_deg}
        else:
            state['pull_forward'] = False

    # Camera points analysis
    left_wall_dists = []
    right_wall_dists = []
    wall_ahead_dist = 999.0

    if cam and 'walls' in cam:
        for b, d in cam['walls']:
            rad = math.radians(b)
            dx = d * math.cos(rad)
            dy = d * math.sin(rad)
            dist_back = -dx

            if 0.5 < dist_back < 12.0:
                if dy > 0.3:
                    left_wall_dists.append(dy)
                elif dy < -0.3:
                    right_wall_dists.append(-dy)
                if abs(dy) < 2.0:
                    if dist_back < wall_ahead_dist:
                        wall_ahead_dist = dist_back

    min_left = min(left_wall_dists) if left_wall_dists else 3.0
    min_right = min(right_wall_dists) if right_wall_dists else 3.0

    # When reversing into a right turn, target a negative hitch angle
    if wall_ahead_dist < 6.5 or (min_right > 3.2 and min_left < 2.8):
        target_hitch = -18.0
    elif min_right > 4.0:
        target_hitch = -15.0
    else:
        lateral_err = (min_left - min_right)
        target_hitch = 5.0 * lateral_err
        target_hitch = max(-20.0, min(20.0, target_hitch))

    target = obs.get('target', {})
    if target.get('in_sight'):
        tb = target.get('bearing_deg', 0.0)
        bearing_back = tb - 180.0 if tb > 0 else tb + 180.0
        target_hitch = 0.8 * bearing_back
        target_hitch = max(-22.0, min(22.0, target_hitch))

    # Hitch control
    err = hitch - target_hitch
    steer = 2.8 * err
    steer = max(-40.0, min(40.0, steer))

    return {'steer_deg': steer, 'speed_mps': -1.0, 'look_deg': look_deg}

